<?php
require __DIR__.'/config.php';
$id=(int)($_GET['id']??0);$stmt=$db->prepare('SELECT * FROM services WHERE id=? AND active=1');$stmt->execute([$id]);$s=$stmt->fetch();if(!$s){http_response_code(404);exit('Servizio non trovato');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $ref=(int)($_POST['ref']??0); $u=$ref?(function()use($db,$ref){$x=$db->prepare("SELECT * FROM users WHERE id=? AND role='partner'");$x->execute([$ref]);return $x->fetch();})():null;
 if($u){$st=$db->prepare('INSERT INTO leads(user_id,service_id,name,email,phone,message) VALUES(?,?,?,?,?,?)');$st->execute([$u['id'],$s['id'],trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['message'])]);$thanks=true;} }
layout_start($s['title']);?><div class="container"><div class="hero"><span class="pill">Servizio</span><h1><?php echo e($s['title']);?></h1><p><?php echo e($s['short_description']);?></p><h2>€ <?php echo number_format((float)$s['price'],2,',','.');?></h2></div><div class="card"><h2>Cosa offre</h2><p><?php echo nl2br(e($s['description']));?></p></div><div class="card"><h2>Richiedi informazioni</h2><?php if(!empty($thanks)):?><p><strong>Grazie.</strong> La richiesta è stata inviata.</p><?php else:?><p class="muted">Per il tracking del partner usa la landing page personale.</p><form method="post"><input type="hidden" name="ref" value="<?php echo (int)($_GET['ref']??0);?>"><label>Nome</label><input name="name" required><label>Email</label><input type="email" name="email"><label>Telefono</label><input name="phone"><label>Messaggio</label><textarea name="message" rows="5"></textarea><button class="btn">Richiedi una consulenza</button></form><?php endif;?></div></div><?php layout_end();?>
